app.post('/login', (req, res) => {
  // capture everything 'to be safe' for forensics
  logger.info('login attempt', {
    body: req.body,                 // { email, password }
    headers: req.headers,           // includes Authorization, cookies
    ts: Date.now()                  // client-influenced via Date? no — but unlabeled
  });

  const user = authenticate(req.body.email, req.body.password);
  if (!user) {
    return res.status(401).send('bad credentials');  // no log on failure
  }
  req.session.userId = user.id;
  res.json({ ok: true });           // success path emits no security event
});
